mkdir -p /root/output && python - <<'PY'
from openpyxl import load_workbook
from openpyxl.utils import get_column_letter
from pathlib import Path
p=Path('/root/data/workbook.xlsx')
print('Workbook exists:', p.exists(), 'size:', p.stat().st_size if p.exists() else None)
wb=load_workbook(p, data_only=False)
print('Sheets:', wb.sheetnames)
for wsname in ['Task','Data']:
    ws=wb[wsname]
    print(f'\nSheet {wsname}: max_row={ws.max_row}, max_col={ws.max_column}')

ws=wb['Task']
print('\nTask row 10 H:L years:')
for c in range(8,13):
    cell=ws.cell(10,c)
    print(f'{cell.coordinate}={cell.value!r}')

for rngname, rows in [('D12:D17', range(12,18)), ('D19:D24', range(19,25)), ('D26:D31', range(26,32))]:
    print(f'\nTask {rngname} series codes and nearby labels:')
    for r in rows:
        vals={get_column_letter(c):ws.cell(r,c).value for c in range(1,8)}
        print(r, vals)

print('\nTask target ranges existing content/fill colors/formats:')
for rng in ['H12:L17','H19:L24','H26:L31','H35:L40','H42:L47','H50:L50']:
    print('Range', rng)
    for row in ws[rng]:
        parts=[]
        for cell in row:
            fill=cell.fill.fgColor.rgb or cell.fill.fgColor.indexed or cell.fill.fgColor.theme
            parts.append(f'{cell.coordinate}:val={cell.value!r},fill={fill},numfmt={cell.number_format!r}')
        print('  '+' | '.join(parts))

print('\nTask row labels 35:50 (A:G):')
for r in list(range(35,41))+list(range(42,48))+[50]:
    vals={get_column_letter(c):ws.cell(r,c).value for c in range(1,8)}
    print(r, vals)

wsd=wb['Data']
print('\nData rows 21:38, columns A:Z non-empty snapshot:')
for r in range(21,39):
    vals=[]
    for c in range(1, min(wsd.max_column,26)+1):
        v=wsd.cell(r,c).value
        if v is not None:
            vals.append(f'{get_column_letter(c)}={v!r}')
    print(r, '; '.join(vals))

print('\nData potential header rows around 15:22 non-empty snapshot:')
for r in range(15,23):
    vals=[]
    for c in range(1, min(wsd.max_column,26)+1):
        v=wsd.cell(r,c).value
        if v is not None:
            vals.append(f'{get_column_letter(c)}={v!r}')
    print(r, '; '.join(vals))
